	b := int(parts2[0][0]-'0')*10 + int(parts2[0][1]-'0')
	if len(parts2[0]) == 1 {
		b = int(parts2[0][0] - '0')
	}
	tb := int(parts2[1][0]-'0')*10 + int(parts2[1][1]-'0')
	if len(parts2[1]) == 1 {
		tb = int(parts2[1][0] - '0')
	}

